import{_ as a,o as t,c as r,a0 as o}from"./chunks/framework.CWG7uS0z.js";const p=JSON.parse('{"title":"专业术语与核心技术核心 (Glossary & Tech Stack)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/terms.md","filePath":"guide/terms.md"}'),n={name:"guide/terms.md"};function s(l,e,i,h,c,d){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="专业术语与核心技术核心-glossary-tech-stack" tabindex="-1">专业术语与核心技术核心 (Glossary &amp; Tech Stack) <a class="header-anchor" href="#专业术语与核心技术核心-glossary-tech-stack" aria-label="Permalink to &quot;专业术语与核心技术核心 (Glossary &amp; Tech Stack)&quot;">​</a></h1><p>在 Farmer Platform 的开发与维护过程中，我们引入了一系列现代化的技术栈。本章节对项目中涉及的<strong>所有核心专业名词</strong>进行了解释，并附带了官方文档链接，便于开发者查阅。</p><hr><h2 id="前端技术-frontend-technologies" tabindex="-1">前端技术 (Frontend Technologies) <a class="header-anchor" href="#前端技术-frontend-technologies" aria-label="Permalink to &quot;前端技术 (Frontend Technologies)&quot;">​</a></h2><h3 id="_1-vue-3" tabindex="-1">1. <a href="https://cn.vuejs.org/" target="_blank" rel="noreferrer">Vue 3</a> <a class="header-anchor" href="#_1-vue-3" aria-label="Permalink to &quot;1. [Vue 3](https://cn.vuejs.org/)&quot;">​</a></h3><ul><li><strong>说明</strong>: 渐进式的 JavaScript 框架，用于构建用户界面。本项目严格采用 <strong>Composition API (组合式 API)</strong>，通过 <code>setup</code> 语法糖组织组件逻辑，使得逻辑复用和代码结构更加清晰。</li><li><strong>应用场景</strong>: <code>src/views</code> 与 <code>src/components</code> 下的所有交互式页面构建。</li></ul><h3 id="_2-vite" tabindex="-1">2. <a href="https://cn.vitejs.dev/" target="_blank" rel="noreferrer">Vite</a> <a class="header-anchor" href="#_2-vite" aria-label="Permalink to &quot;2. [Vite](https://cn.vitejs.dev/)&quot;">​</a></h3><ul><li><strong>说明</strong>: 新一代的前端构建工具。与传统的 Webpack 相比，它利用了浏览器原生的 ES 模块特性（ESM），在开发环境下实现了几乎无延迟的极速冷启动（Cold Start）和热模块替换（HMR）。</li><li><strong>应用场景</strong>: 本项目的开发服务器与生产环境打包工具（由 <code>vite.config.js</code> 驱动）。</li></ul><h3 id="_3-pinia" tabindex="-1">3. <a href="https://pinia.vuejs.org/zh/" target="_blank" rel="noreferrer">Pinia</a> <a class="header-anchor" href="#_3-pinia" aria-label="Permalink to &quot;3. [Pinia](https://pinia.vuejs.org/zh/)&quot;">​</a></h3><ul><li><strong>说明</strong>: Vue 的专属状态管理库（State Management），作为 Vuex 的现代替代品出现。它支持完全类型推断，取消了传统的 Mutations，直接使用 Actions 来进行状态修改。</li><li><strong>应用场景</strong>: 位于 <code>src/stores</code> 目录下，如 <code>auth.js</code> 和 <code>platform.js</code>，负责全局的用户鉴权状态和平台公共状态管理。</li></ul><h3 id="_4-element-plus" tabindex="-1">4. <a href="https://element-plus.org/zh-CN/" target="_blank" rel="noreferrer">Element Plus</a> <a class="header-anchor" href="#_4-element-plus" aria-label="Permalink to &quot;4. [Element Plus](https://element-plus.org/zh-CN/)&quot;">​</a></h3><ul><li><strong>说明</strong>: 基于 Vue 3，面向设计师和开发者的组件库。本项目中进行了深度定制，抛弃了死板的原生样式，结合项目本身的“Harvest”设计语言进行了全局重构。</li><li><strong>应用场景</strong>: UI 组件，如表单输入 <code>&lt;el-input&gt;</code>、弹窗 <code>&lt;el-dialog&gt;</code>、分页 <code>&lt;el-pagination&gt;</code>。</li></ul><h3 id="_5-axios" tabindex="-1">5. <a href="https://axios-http.com/zh/" target="_blank" rel="noreferrer">Axios</a> <a class="header-anchor" href="#_5-axios" aria-label="Permalink to &quot;5. [Axios](https://axios-http.com/zh/)&quot;">​</a></h3><ul><li><strong>说明</strong>: 基于 Promise 的 HTTP 客户端，可运行在浏览器和 Node.js 环境中。本项目通过 <code>src/utils/http.js</code> 对 Axios 进行了请求与响应拦截器（Interceptors）的二次封装。</li></ul><hr><h2 id="后端技术-backend-technologies" tabindex="-1">后端技术 (Backend Technologies) <a class="header-anchor" href="#后端技术-backend-technologies" aria-label="Permalink to &quot;后端技术 (Backend Technologies)&quot;">​</a></h2><h3 id="_1-spring-boot-3" tabindex="-1">1. <a href="https://spring.io/projects/spring-boot" target="_blank" rel="noreferrer">Spring Boot 3</a> <a class="header-anchor" href="#_1-spring-boot-3" aria-label="Permalink to &quot;1. [Spring Boot 3](https://spring.io/projects/spring-boot)&quot;">​</a></h3><ul><li><strong>说明</strong>: 建立在 Spring 框架基础上的快速开发脚手架，以“约定大于配置”为原则，极大简化了企业级 Java 应用的开发流程。Spring Boot 3 是一个重大升级版本，要求 Java 17+ 基线（本项目使用 Java 21）。</li><li><strong>应用场景</strong>: <code>backend/farmer_platform</code> 的整体运行框架。</li></ul><h3 id="_2-java-21" tabindex="-1">2. <a href="https://docs.oracle.com/en/java/javase/21/" target="_blank" rel="noreferrer">Java 21</a> <a class="header-anchor" href="#_2-java-21" aria-label="Permalink to &quot;2. [Java 21](https://docs.oracle.com/en/java/javase/21/)&quot;">​</a></h3><ul><li><strong>说明</strong>: Java 的 LTS（长期支持）版本。引入了虚拟线程（Virtual Threads，提升高并发能力）、记录模式（Record Patterns，简化 DTO 定义）等现代化特性。</li><li><strong>应用场景</strong>: 后端服务的基础运行环境语言。</li></ul><h3 id="_3-spring-data-jpa" tabindex="-1">3. <a href="https://spring.io/projects/spring-data-jpa" target="_blank" rel="noreferrer">Spring Data JPA</a> <a class="header-anchor" href="#_3-spring-data-jpa" aria-label="Permalink to &quot;3. [Spring Data JPA](https://spring.io/projects/spring-data-jpa)&quot;">​</a></h3><ul><li><strong>说明</strong>: 基于 JPA（Java Persistence API）规范的持久层框架，开发者只需定义接口并遵循命名规范，即可自动生成相应的 SQL 执行逻辑，大幅减少模板化代码。</li><li><strong>应用场景</strong>: 实体映射与数据库操作（例如 <code>UserRepository</code> 和 <code>ProductRepository</code>），项目中广泛应用了其内置的 <code>Pageable</code> 进行数据分页。</li></ul><h3 id="_4-jwt-json-web-token" tabindex="-1">4. <a href="https://jwt.io/" target="_blank" rel="noreferrer">JWT (JSON Web Token)</a> <a class="header-anchor" href="#_4-jwt-json-web-token" aria-label="Permalink to &quot;4. [JWT (JSON Web Token)](https://jwt.io/)&quot;">​</a></h3><ul><li><strong>说明</strong>: 一种开放标准 (RFC 7519)，定义了一种紧凑且自包含的方式，用于在各方之间以 JSON 对象安全地传输信息。此信息经过数字签名，可以被验证和信任。</li><li><strong>应用场景</strong>: <code>AuthInterceptor</code> 中进行无状态的用户身份验证。</li></ul><h3 id="_5-dto-data-transfer-object" tabindex="-1">5. DTO (Data Transfer Object) <a class="header-anchor" href="#_5-dto-data-transfer-object" aria-label="Permalink to &quot;5. DTO (Data Transfer Object)&quot;">​</a></h3><ul><li><strong>说明</strong>: 数据传输对象。一种设计模式，用于在系统不同层或不同服务之间传递纯粹的数据。它可以隐藏底层的数据表结构设计，增加数据传输的安全性。</li><li><strong>应用场景</strong>: 位于后端的 <code>dto</code> 包，严格隔离数据库实体与前端接收的数据模型。</li></ul><hr><h2 id="智能化技术-ai-data" tabindex="-1">智能化技术 (AI &amp; Data) <a class="header-anchor" href="#智能化技术-ai-data" aria-label="Permalink to &quot;智能化技术 (AI &amp; Data)&quot;">​</a></h2><h3 id="_1-fastapi" tabindex="-1">1. <a href="https://fastapi.tiangolo.com/" target="_blank" rel="noreferrer">FastAPI</a> <a class="header-anchor" href="#_1-fastapi" aria-label="Permalink to &quot;1. [FastAPI](https://fastapi.tiangolo.com/)&quot;">​</a></h3><ul><li><strong>说明</strong>: 一个现代、快速（高性能）的 Python Web 框架，基于标准的 Python 类型提示。它天生支持异步编程（async/await），是构建高性能 AI 服务的理想选择。</li><li><strong>应用场景</strong>: <code>ai-agent/main.py</code> 中的 RESTful 接口与 SSE 流式推送。</li></ul><h3 id="_2-deepseek-v3" tabindex="-1">2. <a href="https://platform.deepseek.com/" target="_blank" rel="noreferrer">DeepSeek-V3</a> <a class="header-anchor" href="#_2-deepseek-v3" aria-label="Permalink to &quot;2. [DeepSeek-V3](https://platform.deepseek.com/)&quot;">​</a></h3><ul><li><strong>说明</strong>: 一款高智能的大语言模型（LLM）。通过先进的 Transformer 架构训练，擅长长文本总结与逻辑推理。</li><li><strong>应用场景</strong>: 平台的 AI Agent 引擎，提供农产品数据智能聚合与商业报告。</li></ul><h3 id="_3-langchain-python" tabindex="-1">3. <a href="https://python.langchain.com/docs/" target="_blank" rel="noreferrer">LangChain Python</a> <a class="header-anchor" href="#_3-langchain-python" aria-label="Permalink to &quot;3. [LangChain Python](https://python.langchain.com/docs/)&quot;">​</a></h3><ul><li><strong>说明</strong>: 用于开发由大型语言模型（LLMs）驱动的应用的 Python 框架。它通过 <code>bind_tools</code> 和 <code>ainvoke</code> 极大地简化了 LLM 与外部系统（后端 API）的交互。</li><li><strong>应用场景</strong>: 位于 <code>ai-agent/engine</code> 中，负责 Tool Calling 的核心逻辑。</li></ul><h3 id="_4-sse-server-sent-events" tabindex="-1">4. <a href="https://developer.mozilla.org/zh-CN/docs/Web/API/Server-sent_events" target="_blank" rel="noreferrer">SSE (Server-Sent Events)</a> <a class="header-anchor" href="#_4-sse-server-sent-events" aria-label="Permalink to &quot;4. [SSE (Server-Sent Events)](https://developer.mozilla.org/zh-CN/docs/Web/API/Server-sent_events)&quot;">​</a></h3><ul><li><strong>说明</strong>: 一种允许服务器向客户端<strong>单向</strong>推送事件的 Web 技术。利用 HTTP 连接保持打开状态，非常适合 AI 生成的实时打字机效果。</li></ul><hr><h2 id="ui-ux-设计理念" tabindex="-1">UI/UX 设计理念 <a class="header-anchor" href="#ui-ux-设计理念" aria-label="Permalink to &quot;UI/UX 设计理念&quot;">​</a></h2><h3 id="_1-bento-grid-便当盒网格" tabindex="-1">1. Bento Grid (便当盒网格) <a class="header-anchor" href="#_1-bento-grid-便当盒网格" aria-label="Permalink to &quot;1. Bento Grid (便当盒网格)&quot;">​</a></h3><ul><li><strong>说明</strong>: 一种现代化的 UI 布局模式，将信息模块化分割在多个尺寸不一的矩形卡片中，形成错落有致但秩序井然的视觉效果。</li></ul><h3 id="_2-floating-island-悬浮岛屿" tabindex="-1">2. Floating Island (悬浮岛屿) <a class="header-anchor" href="#_2-floating-island-悬浮岛屿" aria-label="Permalink to &quot;2. Floating Island (悬浮岛屿)&quot;">​</a></h3><ul><li><strong>说明</strong>: 导航栏、侧边栏或主要内容区域不与页面边缘直接贴合，而是保留一定的 Margin，并配合柔和的阴影（Drop Shadow），产生元素悬浮在背景色之上的空间层次感。</li></ul>',42)])])}const u=a(n,[["render",s]]);export{p as __pageData,u as default};
